import type { FilterValue } from 'models/Filters';
import { TimePeriodType } from 'utils/timePeriod/timePeriodAvailability';

const QUARTER_CARD_PERIOD_TYPES = new Set(['Q1', 'Q2', 'Q3', 'Q4']);

const isQuarterCardPeriodType = (periodType: string): boolean =>
  QUARTER_CARD_PERIOD_TYPES.has(periodType) ||
  periodType === TimePeriodType.QTR;

/**
 * Maps a big-numbers card period_type to the Volume API period_type,
 * preserving tray-level contracts such as QTR instead of Q1-Q4.
 */
export function getVolumeBigNumbersApiPeriodType(
  cardPeriodType: FilterValue | string,
  trayPeriodType: FilterValue | undefined,
): string | null {
  const normalizedCard = String(cardPeriodType).trim().toUpperCase();
  const normalizedTray = String(trayPeriodType ?? '')
    .trim()
    .toUpperCase();

  if (!normalizedCard) return null;

  if (
    normalizedTray === TimePeriodType.QTR &&
    isQuarterCardPeriodType(normalizedCard)
  ) {
    return TimePeriodType.QTR;
  }

  return normalizedCard;
}
